R='/project1/glsl_test_9'
results={}
results['total_ops']=len(op(R).children)
for c in op(R).children:
    t=str(type(c))
    if 'glslPOP' in t:
        results['glsl_errors']=str(c.errors())
        results['outputattrs']=c.par.outputattrs.eval()
        results['numelems']=c.par.numelems.eval()
        results['num_inputs']=len(c.inputConnectors)
        try:
            results['connected_src_name']=c.inputConnectors[0].op().name
        except:
            results['connected']=str(type(c.inputConnectors[0]))
print(json.dumps(results))
